'use client';

import { useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { WordRoll } from '@/components/core/word-roll';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Chip } from '@/registry/ndeko/ui/chip';
import { Tabs, TabsList, TabsTab } from '@/registry/ndeko/ui/tabs';
import { Wash } from '@/registry/ndeko/ui/wash';

import {
  type BillingPeriod,
  DEFAULT_PERIOD,
  type Plan,
  PLANS,
  SECTION,
} from './data';

const MONTHS_PER_YEAR = 12;

const PERIOD_ORDER: Record<BillingPeriod, number> = {
  monthly: 0,
  yearly: 1,
};

const PRICE_FORMAT: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'USD',
  maximumFractionDigits: 0,
};

const PRICE_FORMATTER = new Intl.NumberFormat('en-US', PRICE_FORMAT);

const PLAN_SURFACE =
  'bg-card hairline-ring ring-border shadow-[0_1px_2px_rgb(0_0_0/0.04)] dark:bg-foreground/[0.03]';

function isBillingPeriod(value: unknown): value is BillingPeriod {
  const isMonthly = value === 'monthly';
  const isYearly = value === 'yearly';
  return isMonthly || isYearly;
}

function formatPrice(amount: number) {
  return PRICE_FORMATTER.format(amount);
}

function monthlyFigureOf(plan: Plan, period: BillingPeriod) {
  if (period === 'yearly') {
    return plan.yearlyPrice / MONTHS_PER_YEAR;
  }
  return plan.monthlyPrice;
}

function billingNoteOf(plan: Plan, period: BillingPeriod) {
  if (period === 'yearly') {
    const total = formatPrice(plan.yearlyPrice);
    return `Billed ${total} once a year`;
  }
  return 'Billed every month';
}

function surfaceOf(plan: Plan) {
  if (plan.isFeatured) {
    return 'surface-brand';
  }
  return PLAN_SURFACE;
}

function actionVariantOf(plan: Plan) {
  if (plan.isFeatured) {
    return 'default' as const;
  }
  return 'outline' as const;
}

type PlanCardProps = {
  plan: Plan;
  period: BillingPeriod;
};

function PlanCard({ plan, period }: PlanCardProps) {
  const figure = monthlyFigureOf(plan, period);
  const note = billingNoteOf(plan, period);
  const periodOrder = PERIOD_ORDER[period];
  const surface = surfaceOf(plan);
  const actionVariant = actionVariantOf(plan);

  return (
    <article
      className={cn(
        'relative isolate flex flex-col gap-6 rounded-xl p-6 sm:p-7',
        surface
      )}
    >
      {plan.isFeatured && <Wash />}
      <div className='flex flex-col gap-1.5'>
        <div className='flex items-center justify-between gap-3'>
          <h3 className='text-sm font-medium'>{plan.name}</h3>
          {plan.tag && <Chip>{plan.tag}</Chip>}
        </div>
        <p className='text-muted-foreground text-[13px]'>{plan.description}</p>
      </div>
      <div aria-live='polite' className='flex flex-col gap-1'>
        <p className='flex items-baseline gap-1.5'>
          <MotionNumber
            value={figure}
            format={PRICE_FORMAT}
            className='text-4xl font-semibold'
          />
          <span className='text-muted-foreground text-[13px]'>per month</span>
        </p>
        <p className='text-muted-foreground text-xs tabular-nums'>
          <WordRoll text={note} value={periodOrder} />
        </p>
      </div>
      <Button
        size='lg'
        variant={actionVariant}
        nativeButton={false}
        render={<a href='#' />}
      >
        {plan.action}
      </Button>
      <ul className='flex flex-col gap-2.5 text-[13px]'>
        {plan.features.map((feature) => (
          <li key={feature} className='flex items-center gap-2.5'>
            <span
              aria-hidden='true'
              className='bg-foreground/25 size-1 shrink-0 rounded-full'
            />
            {feature}
          </li>
        ))}
      </ul>
    </article>
  );
}

export default function Pricing01() {
  const [period, setPeriod] = useState<BillingPeriod>(DEFAULT_PERIOD);

  function changePeriod(value: unknown) {
    if (isBillingPeriod(value)) {
      setPeriod(value);
    }
  }

  return (
    <section className='px-4 py-16 sm:px-6 sm:py-24 lg:px-8'>
      <div className='mx-auto flex max-w-4xl flex-col gap-10'>
        <div className='grid gap-6 md:grid-cols-[minmax(0,1fr)_auto] md:items-end'>
          <div className='flex flex-col gap-3'>
            <h2 className='text-2xl font-semibold text-balance sm:text-3xl'>
              {SECTION.title}
            </h2>
            <p className='text-muted-foreground max-w-lg text-base text-pretty'>
              {SECTION.description}
            </p>
          </div>
          <div className='flex items-center gap-3'>
            <Tabs value={period} onValueChange={changePeriod}>
              <TabsList variant='segmented' aria-label='Billing period'>
                <TabsTab value='monthly'>Monthly</TabsTab>
                <TabsTab value='yearly'>Yearly</TabsTab>
              </TabsList>
            </Tabs>
            <Badge variant='secondary' className='text-muted-foreground'>
              {SECTION.yearlyNote}
            </Badge>
          </div>
        </div>
        <div className='grid gap-4 md:grid-cols-2'>
          {PLANS.map((plan) => (
            <PlanCard key={plan.id} plan={plan} period={period} />
          ))}
        </div>
        <p className='text-muted-foreground text-xs'>{SECTION.footnote}</p>
      </div>
    </section>
  );
}

export type BillingPeriod = 'monthly' | 'yearly';

export type Plan = {
  id: string;
  name: string;
  description: string;
  monthlyPrice: number;
  yearlyPrice: number;
  features: string[];
  action: string;
  isFeatured: boolean;
  tag?: string;
};

export const DEFAULT_PERIOD: BillingPeriod = 'monthly';

export const SECTION = {
  title: 'Two plans, both with every editor feature',
  description:
    'Start alone and move to Studio when other people write with you. Your subscribers and archive come along.',
  yearlyNote: 'Two months free',
  footnote: 'Example prices in US dollars, taxes added at checkout',
};

export const PLANS: Plan[] = [
  {
    id: 'writer',
    name: 'Writer',
    description: 'For one person and one newsletter',
    monthlyPrice: 12,
    yearlyPrice: 120,
    features: [
      'One newsletter',
      'Up to 2,000 subscribers',
      'Scheduled sends',
      'Your own domain',
    ],
    action: 'Start with Writer',
    isFeatured: false,
  },
  {
    id: 'studio',
    name: 'Studio',
    description: 'For a small team with several publications',
    monthlyPrice: 30,
    yearlyPrice: 300,
    features: [
      'Everything in Writer',
      'Up to five newsletters',
      'Up to 20,000 subscribers',
      'Three editor seats',
      'Paid subscriptions',
    ],
    action: 'Start with Studio',
    isFeatured: true,
    tag: 'For teams',
  },
];
